const results = $input.first().json.results || [];
const wh = $('Webhook').first().json;
const req = wh.body || wh.query || wh || {};

function abstractText(inv) {
  if (!inv) return '';
  const words = [];
  for (const [word, positions] of Object.entries(inv)) {
    for (const p of positions) words[p] = word;
  }
  return words.join(' ');
}

const papers = results
  .map(p => ({
    title: p.title,
    year: p.publication_year,
    venue: p.primary_location?.source?.display_name || '',
    url: p.doi || p.id,
    abstract: abstractText(p.abstract_inverted_index)
  }))
  .filter(p => p.abstract && p.title);

return [{ json: {
  topic: req.topic,
  audience: req.target_audience,
  raw_sources: papers.map((p, i) =>
    `[${i + 1}] ${p.title} (${p.year}) ${p.venue}\nURL: ${p.url}\n${p.abstract}`
  ).join('\n\n')
}}];

const item = $input.first().json;
let t = String(item.text ?? item.output ?? item.response ?? '').trim();

const start = t.indexOf('{');
if (start === -1) {
  throw new Error('Modelden JSON gelmedi. Gelen metin: ' + t.slice(0, 300));
}
const end = t.lastIndexOf('}');
const raw = t.slice(start, end > start ? end + 1 : t.length);

function tryParse(s) { try { return JSON.parse(s); } catch (e) { return null; } }

// Bozuk JSON'u onarır: kaçışsız tırnak, satır sonu, kesilmiş çıktı
function repair(s) {
  let out = '', inStr = false, esc = false;
  const stack = [];
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (!inStr) {
      if (c === '"') inStr = true;
      else if (c === '{' || c === '[') stack.push(c === '{' ? '}' : ']');
      else if (c === '}' || c === ']') stack.pop();
      out += c;
      continue;
    }
    if (esc) { out += c; esc = false; continue; }
    if (c === '\\') { out += c; esc = true; continue; }
    if (c === '"') {
      let j = i + 1;
      while (j < s.length && /\s/.test(s[j])) j++;
      const n = s[j];
      if (n === undefined || n === ',' || n === '}' || n === ']' || n === ':') {
        out += c; inStr = false;
      } else {
        out += '\\"';
      }
      continue;
    }
    if (c === '\n') { out += '\\n'; continue; }
    if (c === '\r') { continue; }
    if (c === '\t') { out += ' '; continue; }
    out += c;
  }
  if (inStr) out += '"';
  out = out.replace(/,\s*$/, '');
  while (stack.length) out += stack.pop();
  return out.replace(/,\s*([}\]])/g, '$1');
}

let d = tryParse(raw);
if (!d) d = tryParse(repair(raw));
if (!d) {
  let msg = '';
  try { JSON.parse(repair(raw)); } catch (e) { msg = e.message; }
  throw new Error('JSON onarılamadı: ' + msg + ' | Başlangıç: ' + raw.slice(0, 150));
}

const wh = $('Webhook').first().json;
const req = wh.body || wh.query || wh || {};
d.status = 'success';
d.meta = { topic: req.topic, generated_at_timestamp: new Date().toISOString() };
d.articles = Array.isArray(d.articles) ? d.articles : [];
d.visual_diagrams = Array.isArray(d.visual_diagrams) ? d.visual_diagrams : [];

return [{ json: d }];
